using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
public class SortGenericLayer : ComponentBase
{
	public string sortingLayer = string.Empty;
	public float yValueOffset;
	public int yLayerOffset;
	public bool sortOnlyOnce;
	public bool sortBySpriteTransform = true;
	protected Type type;
	protected Type sorterType;
	protected IList iList;
	protected int iListCount;
	protected Transform baseTransform;
	protected List<SortGenericLayer> childSorterList;
	public virtual void SetType()
	{
	}
	public virtual void HandleSetSortOrder()
	{
	}
	public virtual void Awake()
	{
		if (sortingLayer == string.Empty)
		{
			sortingLayer = "Default";
			Debug.Log("Sorting Layer not set for: " + ((!(transform.parent == null)) ? (transform.parent.gameObject.name + "/") : string.Empty) + gameObject.name + ". Setting to Default.");
		}
		SetType();
		CreateList();
		baseTransform = transform;
		iList = GetComponentsInChildren(type).ToList();
		childSorterList = GetComponentsInChildren<SortGenericLayer>().ToList();
		childSorterList.Remove(this);
	}
	public new virtual void Start()
	{
		for (int i = 0; i < childSorterList.Count; i++)
		{
			SortGenericLayer sortGenericLayer = childSorterList[i];
			if (sortGenericLayer.GetType() != sorterType || sortGenericLayer.sortingLayer != sortingLayer)
			{
				childSorterList.RemoveAt(i);
				i--;
