	{
		if (orbitTrans != null)
		{
			movement.InitOrbitAngle((orbitTrans.position - transform.position).normalized);
		}
	}
	private void Update()
	{
		if (!isDead)
		{
			movement.orbit = allowOrbit;
			if (orbitTrans == null)
			{
				DestroyAttackOrb();
			}
			else
			{
				movement.OrbitTarget(orbitTrans.position);
			}
		}
	}
	public void DestroyAttackOrb()
	{
		isDead = true;
		Object.Destroy(gameObject);
