private void Awake()
{
	entitySprites = new List<SpriteRenderer>();
	spriteList = transform.GetComponentsInChildren<SpriteRenderer>();
	SpriteRenderer[] array = spriteList;
	foreach (SpriteRenderer spriteRenderer in array)
	{
		if (spriteRenderer.gameObject.name.Contains("Sprite"))
		{
			entitySprites.Add(spriteRenderer);
			originalColor = spriteRenderer.color;
			break;
		}
	}
	healthStat.minMaxVal = 1f;
	allowOverheal = new BoolVarStat(newBaseVal: false);
	shieldStat = new NumVarStat(100);
	shieldStat.CurrentValue = 0f;
	damageTakenStat = new SyncedNumVarStat(1f);
	hitStunModifierStat = new SyncedNumVarStat(1f);
	knockbackModifierStat = new SyncedNumVarStat(1f);
	healModifierStat = new SyncedNumVarStat(1f);
	damageCapStat = new SyncedNumVarStat(-1f);
	if (applyIgnoreHurtMod)
	{
		ignoreHurtVarStat.AddMod(baseIgnoreMod);
	}
	if (applyIgnoreKnockbackMod)
	{
		ignoreKnockbackVarStat.AddMod(baseIgnoreMod);
	}
}
