	public virtual float GetElementalDamageModifier(ElementType damageType)
	{
		if (damageType == ElementType.Neutral)
		{
			return 1f;
		}
		eleDmgModVal = 0;
		if (entityScript != null)
		{
			tempEleType = entityScript.element;
			if (tempEleType == damageType)
			{
				eleDmgModVal = -2;
			}
			else if (eleWheelDict.ContainsKey(tempEleType) && eleWheelDict[tempEleType] == damageType)
			{
				eleDmgModVal = 2;
			}
			else if (eleWheelDict.ContainsKey(damageType) && eleWheelDict[damageType] == tempEleType)
			{
				eleDmgModVal = -1;
			}
		}
		return 1f + (float)eleDmgModVal * baseEleBoostValue;
	}
	public void HandleOverdriveProgress(AttackInfo givenInfo)
	{
		if (handleOverdriveEvent != null)
		{
			handleOverdriveEvent(this, givenInfo);
		}
		if (ignoreOverdriveProgress)
		{
			if (!forceOverdriveGain)
			{
				return;
			}
			forceOverdriveGain = false;
		}
		if (!givenInfo.isUltimate && !(givenInfo.entity == null) && givenInfo.entity is Player && !(givenInfo.entity as Player).overdriveReady && (!atkObjIDDict.ContainsKey(givenInfo.atkObjID) || !(atkObjIDDict[givenInfo.atkObjID].First
		{
			atkObjIDDict[givenInfo.atkObjID] = new Tuple<string, float>(givenInfo.attackInfoKey, givenInfo.time);
			tempODIncAmount = 0f;
			if (enemyEntity != null)
			{
				tempODIncAmount = 0.25f * (float)givenInfo.damage * givenInfo.odProgMultiplier;
			}
			else if (destructibleEntity != null)
			{
				tempODIncAmount = 3f * givenInfo.odProgMultiplier;
			}
			else if (playerEntity != null)
			{
				tempODIncAmount = 0.25f * (float)givenInfo.damage * givenInfo.odProgMultiplier * PvpController.pvpOverdriveIncrementModifier;
			}
			if (tempODIncAmount != 0f)
			{
				(givenInfo.entity as Player).OverdriveProgress += tempODIncAmount;
			}
		}
	}
	public bool HandleChaosStatusEffect(AttackInfo givenInfo, Entity atkEnt = null)
	{
		if (givenInfo.chaosChance > 0f && givenInfo.chaosChance > Random.value)
		{
			entityScript.dotManager.AddDot(new ChaosDotEffect(givenInfo.skillCategory, givenInfo.chaosLevel, entityScript, atkEnt));
			return true;
		}
		return false;
	}
	public bool HandleFireStatusEffect(AttackInfo givenInfo, Entity atkEnt = null)
	{
		if (!ignoreBurn.CurrentValue && entityElement != ElementType.Fire && givenInfo.burnChance > 0f && givenInfo.burnChance * statusResDict[ElementType.Fire].CurrentValue > Random.value)
		{
			entityScript.dotManager.AddDot(new BurnDoTEffect(givenInfo.skillCategory, givenInfo.burnLevel, entityScript, atkEnt));
			return true;
		}
		return false;
	}
	public bool HandleAirStatusEffect(AttackInfo givenInfo, Entity atkEnt = null)
	{
