	public IEnumerator RegenHealth(float healAmount, float regenRate = 20f, float timePerTick = 0.2f, float initialHealAmount = 0f)
	{
		float totalRegenAmount = healAmount;
		float healthPerTick = regenRate * timePerTick;
		bool healthPerTickIsInt = true;
		bool roundedUp = true;
		int tickStopwatchID = -1;
		if (initialHealAmount > 0f)
		{
			RestoreHealth((int)initialHealAmount);
			tickStopwatchID = ChaosStopwatch.Begin(timePerTick);
		}
		if (healthPerTick != Mathf.Ceil(healthPerTick))
		{
			healthPerTickIsInt = false;
		}
		while (totalRegenAmount > 0f)
		{
			if ((float)CurrentHealthValue >= healthStat.ModifiedValue || CurrentHealthValue <= 0)
			{
				totalRegenAmount = 0f;
				break;
			}
			if (ChaosStopwatch.Check(tickStopwatchID))
			{
				tickStopwatchID = ChaosStopwatch.Begin(timePerTick);
				if (!healthPerTickIsInt)
				{
					int roundedHealPerTick;
					if (roundedUp)
					{
						roundedHealPerTick = Mathf.CeilToInt(healthPerTick);
						roundedUp = false;
					}
					else
					{
						roundedHealPerTick = Mathf.FloorToInt(healthPerTick);
						roundedUp = true;
					}
					if ((float)roundedHealPerTick > totalRegenAmount)
					{
						roundedHealPerTick = (int)totalRegenAmount;
					}
					RestoreHealth(roundedHealPerTick);
					totalRegenAmount -= (float)roundedHealPerTick;
				}
				else
				{
					RestoreHealth((int)healthPerTick);
					totalRegenAmount -= healthPerTick;
				}
			}
			yield return null;
		}
	}
